import React, { useEffect, useState, useRef } from "react";
import "./App.css";

// PUBLIC_INTERFACE
/**
 * MiniMayhem Arcade Landing Page - Neon Glassmorphic, Retro Arcade, Fun!
 * - Central animated card, About, Joke/Quote/Fact sections.
 * - Dynamic fetch from JokeAPI, Quotable.io, and static Game Fact.
 * - 15s auto-refresh, emoji/icon-rich, glass effect, neon glow, arcade font.
 */
function LandingPage() {
  // FACT: Just for fun, static game fact (could use other trivia APIs if available)
  const GAME_FACTS = [
    "The first video game ever created was 'Tennis for Two' in 1958! 🎾",
    "Pac-Man's original name was 'Puck Man' in Japan. 👻🍒",
    "The highest arcade score ever was in Donkey Kong! 🦍🏆",
    "Nintendo started as a playing card company. 🃏🎮",
    "Space Invaders caused a coin shortage in Japan. 👾💰",
    "Press Start 2P is a font inspired by arcade screens! 🕹️😀",
    "Retro games inspire modern indie hits. ✨🎲",
    "Sonic was nearly a rabbit before becoming a hedgehog! 🦔🐇",
  ];

  // State for dynamic content
  const [joke, setJoke] = useState({ text: "Loading...", error: false });
  const [quote, setQuote] = useState({ text: "Loading...", author: "", error: false });
  const [fact, setFact] = useState({ text: GAME_FACTS[0] });
  const [isFading, setIsFading] = useState(true);
  const [refreshKey, setRefreshKey] = useState(0);

  const refreshInterval = 15000;
  const factIdx = useRef(0);

  // Animation: Fade-in on mount
  useEffect(() => {
    setIsFading(true);
    const introTimeout = setTimeout(() => setIsFading(false), 1000);
    return () => clearTimeout(introTimeout);
  }, []); // Only run on mount

  // Fetch all fun/extras together
  const fetchAll = async () => {
    // Joke from JokeAPI
    let jokeData = { text: "Couldn't load joke.", error: true };
    try {
      const resp = await fetch("https://v2.jokeapi.dev/joke/Any?type=single,twopart", { cache: "no-store" });
      if (resp.ok) {
        const data = await resp.json();
        if (data.type === "single") {
          jokeData = { text: data.joke, error: false };
        } else if (data.type === "twopart") {
          jokeData = { text: `${data.setup} 🤔\n${data.delivery}`, error: false };
        }
      }
    } catch {}
    setJoke(jokeData);

    // Quote from Quotable.io
    let quoteData = { text: "Couldn't fetch quote.", author: "", error: true };
    try {
      const resp = await fetch("https://api.quotable.io/random?minLength=25&maxLength=95", { cache: "no-store" });
      if (resp.ok) {
        const data = await resp.json();
        quoteData = { text: data.content, author: data.author, error: false };
      }
    } catch {}
    setQuote(quoteData);

    // Rotate fun Game Fact (loop)
    factIdx.current = (factIdx.current + 1) % GAME_FACTS.length;
    setFact({ text: GAME_FACTS[factIdx.current] });
  };

  // On first render and every 15s, refresh all fun content
  useEffect(() => {
    fetchAll();
    const timer = setInterval(() => {
      setRefreshKey((k) => k + 1);
      fetchAll();
    }, refreshInterval);
    return () => clearInterval(timer);
    // eslint-disable-next-line
  }, []); // Only on mount

  // Manual refresh "🔁" button (set refreshKey forces effect)
  const handleManualRefresh = () => {
    setIsFading(true);
    setTimeout(() => setIsFading(false), 400);
    setRefreshKey((k) => k + 1);
    fetchAll();
  };

  // Helper for glass card fade effect
  const fadeClass = isFading ? "mmarcade-fadein" : "mmarcade-finish";

  return (
    <div className="mmarcade-bg">
      <main className="mmarcade-flex-center">
        <section className={`mmarcade-card ${fadeClass}`}>
          <header className="mmarcade-header">
            <span className="mmarcade-logoemoji" aria-label="Game Controller" title="MiniMayhem">
              🕹️✨
            </span>
            <h1
              className="mmarcade-title"
              tabIndex="0"
              aria-label="MiniMayhem Arcade"
            >
              MiniMayhem Arcade
            </h1>
            <div className="mmarcade-glowbar" />
          </header>
          <div className={`mmarcade-blurb ${fadeClass}`}>
            <p>
              <span role="img" aria-label="Hey">👾</span> 
              Welcome, Challenger! Bold enough for our mini-game madness?<br />
              <span className="mmarcade-emph">Press Start!</span>
            </p>
          </div>
          <section className={`mmarcade-about ${fadeClass}`}>
            <h2>
              <span role="img" aria-label="About">📝</span> About MiniMayhem
            </h2>
            <p>
              <span role="img" aria-label="Arcade games">🎮</span>
              Dive into quirky quick games, sharp leaderboards, and arcade glory.<br />
              <span role="img" aria-label="Fun">😄</span>
              Get random jokes, glowing facts, and wisdom between plays.<br />
              <span className="mmarcade-emph">100% fun. 0% quarters needed!</span>
            </p>
          </section>
          <div className="mmarcade-divider" />
          <section className="mmarcade-funextras-grid">
            <div className={`mmarcade-glassbox mmarcade-fun-joke ${fadeClass}`}>
              <div className="mmarcade-fun-title">
                <span role="img" aria-label="Joke">🤣</span> Joke of the Moment
                <button
                  className="mmarcade-refresh"
                  title="Refresh joke, quote, fact"
                  aria-label="Refresh"
                  onClick={handleManualRefresh}
                  tabIndex={0}
                >🔁</button>
              </div>
              <p className={`mmarcade-fun-content ${joke.error ? "mmarcade-err" : ""}`}>
                {joke.text}
              </p>
            </div>
            <div className={`mmarcade-glassbox mmarcade-fun-quote ${fadeClass}`}>
              <div className="mmarcade-fun-title">
                <span role="img" aria-label="Quote">💡</span> Arcade Quote
              </div>
              <p className={`mmarcade-fun-content ${quote.error ? "mmarcade-err" : ""}`}>
                "{quote.text}" <br />
                <span className="mmarcade-fun-author">{quote.author && ("- " + quote.author)}</span>
              </p>
            </div>
            <div className={`mmarcade-glassbox mmarcade-fun-fact ${fadeClass}`}>
              <div className="mmarcade-fun-title">
                <span role="img" aria-label="Fact">📚</span> Game Fact
              </div>
              <p className="mmarcade-fun-content">{fact.text}</p>
            </div>
          </section>
        </section>
      </main>
    </div>
  );
}

